// Turns a tool name plus arguments into one of a fixed set of queries.
//
// The model never supplies SQL. It picks a tool and fills in parameters, and the
// SQL is written here — so a confused model cannot produce a table scan that
// starves the triage pipeline of the one Ollama slot and the one small CPU.
//
// Arguments are inlined rather than bound because the Postgres node's parameter
// support varies by operation; every value is therefore passed through `lit()`
// or `num()`, which is the only place user-controlled text reaches a query.
const body = $input.item.json.body || {};
const tool = String(body.tool || '');
const args = body.args && typeof body.args === 'object' ? body.args : {};

// Single-quote escaping for a Postgres string literal. Doubling the quote is the
// documented escape; the leading E'' form is avoided so backslashes stay literal.
const lit = (v) => "'" + String(v == null ? '' : v).replace(/'/g, "''") + "'";
const num = (v, dflt, max) => {
  const n = Number.parseInt(v, 10);
  if (!Number.isFinite(n) || n < 1) return dflt;
  return Math.min(n, max);
};
const inList = (v, allowed) => (allowed.includes(String(v)) ? String(v) : null);

const SEV = ['Critical', 'Urgent', 'Standard'];
const CAT = ['Medical', 'Structural', 'Supply'];
const STATUS = ['New', 'Acknowledged', 'Dispatched', 'Resolved', 'Duplicate'];

let sql;

switch (tool) {
  case 'queue_summary':
    sql = "SELECT * FROM queue_health";
    break;

  case 'search_requests': {
    const COLS = 'id, received_at, severity, category, status, needs_review,'
               + ' reporter_name, location_text, people_affected, summary, raw_message, duplicate_of';
    const ORDER = "ORDER BY CASE severity WHEN 'Critical' THEN 0 WHEN 'Urgent' THEN 1 ELSE 2 END, received_at";
    const limit = num(args.limit, 20, 100);

    const base = ["status IN ('New','Acknowledged','Dispatched')"];
    if (args.text) {
      // Searches the words the person actually wrote, plus the summary.
      const needle = lit('%' + String(args.text) + '%');
      base.push('(raw_message ILIKE ' + needle + ' OR summary ILIKE ' + needle
              + ' OR location_text ILIKE ' + needle + ')');
    }

    // Narrowing filters are kept separate from the text search, because a small
    // model fills in every optional parameter it is offered — including ones the
    // question never mentioned. Observed: a search for "insulin" arrived with
    // severity='Standard' invented alongside it, which excluded the two Urgent
    // rows that matched, and the agent then truthfully reported none.
    const narrow = [];
    const sev = inList(args.severity, SEV);
    if (sev) narrow.push('severity = ' + lit(sev));
    const cat = inList(args.category, CAT);
    if (cat) narrow.push('category = ' + lit(cat));
    const st = inList(args.status, STATUS);
    if (st) narrow.push('status = ' + lit(st));
    if (args.needs_review === true || args.needs_review === 'true') narrow.push('needs_review');

    if (!narrow.length) {
      sql = 'SELECT ' + COLS + ', false AS filters_relaxed FROM requests'
          + ' WHERE ' + base.join(' AND ') + ' ' + ORDER + ' LIMIT ' + limit;
      break;
    }

    // Guessed filters must not be able to hide a matching request. If the
    // narrowed search finds nothing, fall back to the text alone and say so, so
    // "no results" always means no results rather than bad filters. A
    // deterministic backstop, not a plea for the model to behave.
    // Each UNION branch is parenthesised: Postgres rejects a branch carrying its
    // own ORDER BY and LIMIT otherwise.
    sql = 'SELECT * FROM ('
        + '  (SELECT ' + COLS + ', false AS filters_relaxed FROM requests'
        + '    WHERE ' + base.concat(narrow).join(' AND ') + ' ' + ORDER + ' LIMIT ' + limit + ')'
        + '  UNION ALL'
        + '  (SELECT ' + COLS + ', true AS filters_relaxed FROM requests'
        + '    WHERE ' + base.join(' AND ')
        + '      AND NOT EXISTS (SELECT 1 FROM requests r2 WHERE '
        + base.concat(narrow).join(' AND ').replace(/\b(status|severity|category|needs_review|raw_message|summary|location_text)\b/g, 'r2.$1')
        + ')'
        + '    ' + ORDER + ' LIMIT ' + limit + ')'
        + ') q ' + ORDER;
    break;
  }

  case 'get_request': {
    const id = num(args.id, 0, 2147483647);
    if (!id) { sql = 'SELECT NULL WHERE false'; break; }
    // The row plus everything else from the same reporter, because a repeat is
    // usually an escalation and reading one message of four is misleading.
    sql = 'SELECT r.id, r.received_at, r.severity, r.category, r.status,'
        + ' r.needs_review, r.triage_error, r.reporter_name, r.location_text,'
        + ' r.people_affected, r.summary, r.raw_message, r.assigned_to,'
        + ' r.coordinator_notes, r.duplicate_of,'
        + ' (SELECT json_agg(json_build_object(\'id\', s.id, \'received_at\', s.received_at,'
        + "   'severity', s.severity, 'raw_message', s.raw_message) ORDER BY s.received_at)"
        + '  FROM requests s WHERE s.dedupe_key = r.dedupe_key AND s.dedupe_key IS NOT NULL'
        + '    AND s.id <> r.id) AS other_submissions_from_reporter'
        + ' FROM requests r WHERE r.id = ' + id;
    break;
  }

  case 'requests_by_reporter': {
    if (!args.name) { sql = 'SELECT NULL WHERE false'; break; }
    sql = 'SELECT id, received_at, severity, category, status, location_text,'
        + ' summary, raw_message FROM requests'
        + ' WHERE reporter_name ILIKE ' + lit('%' + String(args.name) + '%')
        + ' ORDER BY received_at DESC LIMIT ' + num(args.limit, 20, 100);
    break;
  }

  case 'location_hotspots':
    // Clusters by location rather than by reporter, which is what the dedupe
    // trigger cannot see: several different households on one street is a
    // structural problem, not four unrelated requests.
    sql = 'SELECT lower(regexp_replace(location_text, \'[^[:alnum:]]+\', \'\', \'g\')) AS place_key,'
        + ' min(location_text) AS location, count(*) AS requests,'
        + " count(*) FILTER (WHERE severity = 'Critical') AS critical,"
        + ' count(DISTINCT dedupe_key) AS distinct_reporters,'
        + ' max(received_at) AS latest'
        + " FROM requests WHERE status IN ('New','Acknowledged','Dispatched')"
        + ' GROUP BY 1 HAVING count(*) > 1'
        + ' ORDER BY critical DESC, requests DESC LIMIT ' + num(args.limit, 20, 100);
    break;

  case 'review_pile':
    sql = 'SELECT id, reason, minutes_open, severity, category, reporter_name,'
        + ' location_text, raw_message FROM review_pile LIMIT ' + num(args.limit, 25, 100);
    break;

  default:
    return { json: { tool, error: 'unknown tool: ' + tool, rows: [] } };
}

// _query_pending is a tripwire. The Postgres node continues on error, and when it
// does n8n forwards THIS item unchanged — so without a marker the collector
// cannot tell a query result from a query that never ran, and counts the SQL
// string as one matching request. That produced an agent confidently answering
// "there is 1 request" to every question, from a broken credential.
return { json: { tool, sql, _query_pending: true } };

// Collects the query's rows into one payload. Must not throw: the MCP server
// turns an error here into a tool error the agent can see, but an exception
// would surface as an empty body it cannot interpret.
const tool = $('Build Query').first().json.tool;
const items = $input.all();

const rows = [];
let error = null;

for (const item of items) {
  const j = item.json || {};

  // The tripwire from Build Query. Seeing it here means the Postgres node did
  // not run the query and forwarded its input instead — a bad credential, an
  // unreachable database, a SQL error. Reporting this as data is how a broken
  // node turns into a confident wrong answer, so it is an error, loudly.
  if (j._query_pending) {
    error = 'the database query did not run — check the Triage Postgres (read-only) credential and that role triage_ro exists';
    continue;
  }

  if (j.error) { error = String(j.error.message || j.error).slice(0, 300); continue; }
  // A query with no matches yields a single empty object from alwaysOutputData.
  if (Object.keys(j).length === 0) continue;
  rows.push(j);
}

// An error means the row list is meaningless; do not hand back a count that
// looks like an answer.
if (error) return [{ json: { tool, row_count: 0, rows: [], error } }];

return [{ json: { tool, row_count: rows.length, rows: rows.slice(0, 100), error: null } }];
